-- Per-shot continuity ledger. A shot's start_state must match the previous
-- shot's end_state unless the script's action changes something between them,
-- so props/wardrobe stop teleporting between separately-generated shot images.
-- Generated by the storyboard model alongside the prompts; nullable so rows
-- predating this column (and any shot the model leaves blank) still read fine.
-- No _override counterpart — this is generation metadata, not copyable prompt
-- text, so there is nothing for the user to edit and restore.
alter table shots
  add column start_state text,
  add column end_state text;
